// Only the fixed schema-admission meta-schema is precompiled. Caller schemas
// remain dynamic. Run through npm run generate; never edit generated files.
import Ajv from 'ajv';
import addFormats from 'ajv-formats';
import standalone from 'ajv/dist/standalone/index.js';
import { writeFile } from 'node:fs/promises';
const directory = new URL('../src/infrastructure/runtime/', import.meta.url);
const rules = {};
for (const profile of ['helper', 'collection']) {
  const ajv = new Ajv({ ...(profile === 'helper' ? { allErrors: true, strict: false, strictSchema: true } : { allErrors: false, strict: false }), code: { source: true } });
  if (profile === 'helper') addFormats(ajv);
  rules[profile] = Object.keys(ajv.RULES.all);
  const name = `schemaMeta.${profile}.generated`;
  await writeFile(new URL(name + '.cjs', directory), '// Generated by scripts/generate-browser-schema.mjs. Do not edit.\n' + standalone(ajv, ajv.getSchema('http://json-schema.org/draft-07/schema')) + '\n');
  await writeFile(new URL(name + '.d.cts', directory), '// Generated by scripts/generate-browser-schema.mjs. Do not edit.\ndeclare const validate: (schema: unknown) => boolean;\nexport = validate;\n');
  if (profile === 'helper') await writeFile(new URL('schemaKeywords.generated.json', directory), JSON.stringify(Object.keys(ajv.RULES.keywords)) + '\n');
}
await writeFile(new URL('schemaRules.generated.json', directory), JSON.stringify(rules) + '\n');
